// The obvious next step after https://www.shadertoy.com/view/X3KcWd  :)
// inspired by https://www.shadertoy.com/view/4sVfWw
// but unfinished it looked interesting so went with it

float rand3(vec3 p) {
    p += 17.;
    p *= 1.45;
    return fract(sin( dot(p,p.yzx) ));
}

#define COLOR(X) (.5 + .5 * cos( (X) * 5. * 7. + vec3(0,iTime,-.7*iTime) )) 

void mainImage(out vec4 O,vec2 U)
{
    vec2 R = iResolution.xy, u = (U+U-R) / min(R.x,R.y);
    vec3 cam = vec3( .5+.45*sin(iTime*.8), .5+.45*cos(iTime*.6), iTime ), dir = vec3( u, 1 );
    dir = dir / dir.z;
    cam += dir / dir.z * ( ceil(cam.z) - cam.z );
    vec3 col = vec3(0);
    float size = 1.;
    for ( int deep = 0; deep < 50; deep += 1 )
    {
        vec3 camfl = floor(cam/size);
        float type = rand3( camfl );
        if ( type < .2 && ( camfl.x != 0. || camfl.y != 0. || deep > 10 ) ) // somethings there
            if ( type < .05 )
                size *= .25*(.7+.2*sin(iTime*.1)); // divide
            else  {
                if ( length( fract(cam.xy/size)-.5 ) < .3+.1*sin(atan(fract(cam.x/size)-.5,fract(cam.y/size)-.5)*12.*sin(iTime+cam.z)) )
                {
                    col = mix( COLOR( rand3(floor(cam/size)*5.) ), col, clamp( float(deep) / 60., 0., 1. )  );
                   break;  // uncommment for opaque mode
                }
            }
        cam += dir * size; // advance to next Z
    }
    O = vec4( sqrt(col), 1. );
}
